def gen(rng):
    L = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789'
    def word(a, b):
        return ''.join(rng.choice(L) for _ in range(rng.randint(a, b)))
    tests = ['I love india', 'hello', 'one two three four', 'a b', 'a a a a a', 'Zoho Corporation Chennai', 'x1 y2 z3']
