        tests.append(' '.join(word(1, 7) for _ in range(rng.randint(1, 8))))
    tests.append(' '.join(word(1, 39) for _ in range(5000))[:100000].rstrip())
    tests.append(' '.join(word(1, 1) for _ in range(5000)))
    tests.append(' '.join(word(10, 10) for _ in range(5000)))
    tests.append(word(100000, 100000))
    return tests
